import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.Cu3jFwFD.js";const m=JSON.parse('{"title":"Driving","description":"","frontmatter":{},"headers":[],"relativePath":"features/driving/design.md","filePath":"features/driving/design.md","lastUpdated":1794908281000}'),d={name:"features/driving/design.md"};function i(o,t,n,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="driving" tabindex="-1">Driving <a class="header-anchor" href="#driving" aria-label="Permalink to &quot;Driving&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-designed">DESIGNED</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><p>An arcade van: grippy, quick to answer, glued to the road, never flips, and still a bit silly (hang time, a small bounce on landing). The game can be finished with the four drive keys and E alone. Two optional skills sit on top: a drift for sharp turns at speed and a nitro boost for long straights. Serves <strong>Simple to play</strong> and <strong>Bro thinks he&#39;s smart</strong> (a well-timed boost feels clever).</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li><strong>Core:</strong> W/S (or ↑/↓) accelerate and brake/reverse, A/D (or ←/→) steer, E picks up and delivers. These five keys are all the game requires; the pillar stays &quot;4 drive keys + E&quot; (<a class="decision-ref" href="/hex-gdd/GDD#d-057">D‑057</a>).</li><li><strong>Drift (Space, hold):</strong> while held above a minimum speed, sideways grip drops and the van turns quicker and loses a little speed; grip comes back shortly after release. Drift is handling only: it gives no money, nitro or other reward (<a class="decision-ref" href="/hex-gdd/GDD#d-055">D‑055</a>).</li><li><strong>Nitro (Left Shift or left click):</strong> the van has nitro bars (1 at the start, more with the Nitro Tank card). Holding the button burns the current bar for higher top speed and acceleration, with a small instant kick at the start.</li><li>Nitro refills from two sources only (<a class="decision-ref" href="/hex-gdd/GDD#d-056">D‑056</a>): each delivered package adds part of a bar, and the bars refill slowly by themselves; the passive refill pauses for a moment after a boost ends.</li><li>A boost cannot start below a minimum charge. Bars fill in order; only the current bar burns.</li><li>Off the asphalt the van loses top speed and drags; steep slopes cost climbing power and the van slides back from slopes that are too steep, so players keep to the roads.</li><li>The van slides along walls and fences instead of snagging on them.</li><li>Upgrades change speed, grip and acceleration (<a href="./../upgrades/design">upgrades</a>); damage states lower top speed (<a href="./../damage-and-repair/design">damage-and-repair</a>, <a class="decision-ref" href="/hex-gdd/GDD#d-079">D‑079</a>).</li></ol><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td>Drift grip, normal → drifting</td><td>12 → 1.5 <mark class="tune">TUNE</mark></td><td>grip</td><td>Can a new player recover from a drift?</td></tr><tr><td>Drift turn boost</td><td>×1.5 <mark class="tune">TUNE</mark></td><td>factor</td><td></td></tr><tr><td>Drift minimum speed</td><td>6 <mark class="tune">TUNE</mark></td><td>m/s</td><td></td></tr><tr><td>Grip recovery after release</td><td>0.4 <mark class="tune">TUNE</mark></td><td>s</td><td></td></tr><tr><td>Nitro bars at start</td><td>1</td><td>bars</td><td></td></tr><tr><td>Nitro per delivery</td><td>0.34 <mark class="tune">TUNE</mark></td><td>bar</td><td>About 3 deliveries per bar</td></tr><tr><td>Passive nitro refill</td><td>0.04 per s (a full bar in about 25 s) <mark class="tune">TUNE</mark></td><td>bar/s</td><td></td></tr><tr><td>Passive refill pause after a boost</td><td>1.5 <mark class="tune">TUNE</mark></td><td>s</td><td></td></tr><tr><td>Nitro burn</td><td>0.22 per s (a bar lasts about 4.5 s) <mark class="tune">TUNE</mark></td><td>bar/s</td><td></td></tr><tr><td>Minimum charge to start a boost</td><td>0.08 <mark class="tune">TUNE</mark></td><td>bar</td><td></td></tr><tr><td>Boost multiplier (top speed and acceleration)</td><td>×1.3 <mark class="tune">TUNE</mark></td><td>factor</td><td></td></tr><tr><td>Boost start kick</td><td>+3 <mark class="tune">TUNE</mark></td><td>m/s</td><td></td></tr><tr><td>Off-road top-speed loss</td><td>25 <mark class="tune">TUNE</mark></td><td>%</td><td></td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>Drift below the minimum speed does nothing.</li><li>Nitro and drift together are allowed.</li><li>Nitro does not carry between days: every shift starts with empty bars (as in the prototype).</li><li>The van is frozen while a pop-up, the wreck sequence or the pause menu is open.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><mark class="tune">TUNE</mark> All numbers are the prototype&#39;s (ArcadeDrive, NitroSystem).</li><li>The new, smaller city map may need lower top speeds or tighter turns; re-check on that map.</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: designed (<a class="decision-ref" href="/hex-gdd/GDD#d-055">D‑055</a> to <a class="decision-ref" href="/hex-gdd/GDD#d-057">D‑057</a>). Drift and nitro came from the prototype and are now part of the design as optional skills.</li></ul>',13)])])}const u=e(d,[["render",i]]);export{m as __pageData,u as default};
